import assert from 'node:assert/strict';
import {createController} from './src/controller.js';
const pending=[]; const records=[]; const renders=[];
const c=createController({service:{commit(snapshot){return new Promise((resolve,reject)=>pending.push({snapshot,resolve,reject}));}},audit:{record:x=>records.push(x)},render:x=>renders.push(x)});
assert.equal(await c.submit(),null);
c.open('a','u');c.edit('first');const first=c.submit();c.edit('second');const second=c.submit();
assert.deepEqual(pending.map(x=>x.snapshot.text),['first','second']);
pending[0].resolve({revision:1});assert.deepEqual(await first,{revision:1});assert.deepEqual(records,[{doc:'a',actor:'u',text:'first',revision:1}]);assert.deepEqual(renders,[]);
pending[1].reject(new Error('fail'));assert.equal(await second,undefined);assert.deepEqual(renders,[{status:'error',doc:'a'}]);
const third=c.submit();c.close();pending[2].resolve({revision:3});await third;assert.equal(records.length,2);assert.equal(renders.length,1);
const sync=createController({service:{commit(){throw Error('fail');}},audit:{record(){throw Error('unexpected');}},render:x=>renders.push(x)});sync.open('b','v');assert.equal(await sync.submit(),undefined);assert.deepEqual(renders.at(-1),{status:'error',doc:'b'});
console.log('controller async self-check passed');
EOF
